(async () => {
  // pf827-cis-keys-apply (10 Nov 2026): files the CIS answer keys for Chapters 4-12 (Downloads/Add to Obsidian) like the existing keys for Ch. 1-3:
  // the PDF to Library/Sanskrit/Chapter_N.pdf, the Markdown copy to Study/Sanskrit/, the catalog note to Catalog/Sanskrit-Study/.
  // New files only: nothing is overwritten. Dry run lists what would be made; // APPLY makes it.
  const JOB = 'pf827-cis-keys-apply', ad = app.vault.adapter, DRY = window.DRY !== false, fs = require('fs'), path = require('path');
  const D = { when: new Date().toISOString(), dry: DRY, log: [], errors: [] }, L = s => D.log.push(s), E = s => D.errors.push(s);
  const B = {"Study/Sanskrit/CIS - Answers to Chapter 4 Exercises (Ruppel).md": "---\ntype: other\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 4 Exercises\"\nauthor:\n  - Antonia M. Ruppel\nwork: \"[[The Cambridge Introduction to Sanskrit - Answers to Chapter 4 Exercises]]\"\nsource_pdf: Library/Sanskrit/Chapter_4.pdf\npage_range: \"1\"\npdf_pages: 1–1\ntext_source: PDF text layer (born-digital), PyMuPDF; Devanagari the text layer garbles rebuilt from the printed transliteration or read from the page image\nconverted: 2026-11-10\n---\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 4 Exercises\n\nAntonia M. Ruppel.\n\nConverted from the PDF on 10 Nov 2026. Each PDF page starts with `*[p. N]*`, the printed page number (or the PDF page where none is printed), ending in the block id `^pgK` for PDF page K. The PDF stays on the computer: open it from [[The Cambridge Introduction to Sanskrit - Answers to Chapter 4 Exercises|the catalog note]].\n\n> [!note] Devanagari\n> The PDF's text layer garbles most of the Devanagari. It is rebuilt here from the printed transliteration (in 1, from the first forms of each list); check it against the PDF when it matters.\n\n*[p. 1]* ^pg1\n\nCHAPTER 4\n\n1\\)\na\\) muñcāmi, muñcasi, muñcati, muñcāvaḥ, muñcathaḥ, muñcataḥ, muñcāmaḥ, muñcatha, muñcanti (मुञ्चामि, मुञ्चसि etc.)\nb\\) viśāmi, viśasi, viśati, viśāvaḥ, viśathaḥ, viśataḥ, viśāmaḥ, viśatha, viśanti (विशामि, विशसि etc.)\nc\\) hṛṣyāmi, hṛṣyasi, hṛṣyati, hṛṣyāvaḥ, hṛṣyathaḥ, hṛṣyataḥ, hṛṣyāmaḥ, hṛṣyatha, hṛṣyanti (हृष्यामि, हृष्यसि etc.)\nd\\) smarāmi, smarasi, smarati, smarāvaḥ, smarathaḥ, smarataḥ, smarāmaḥ, smaratha, smaranti (स्मरामि, स्मरसि etc.)\ne\\) bodhāmi, bodhasi, bodhati, bodhāvaḥ, bodhathaḥ, bodhataḥ, bodhāmaḥ, bodhatha, bodhanti (बोधामि, बोधसि etc.)\n\n2\\)\n1\\) bodhati: 3rd SG of √budh ‘to awake’ –› ‘he/she awakes’\n2\\) bharatha: 2nd PL of √bhṛ ‘to carry’ –› ‘you carry’ (alternatively: ‘you (many) carry’, ‘you all /y’all carry’)\n3\\) harasi: 2nd SG of √hṛ ‘to take’ –› ‘you take’\n4\\) viśāvaḥ: 1st DU of √viś ‘to enter’ –› ‘we both enter’\n5\\) smaranti: 3rd PL of √smṛ ‘to remember’ –› ‘they remember’\n6\\) kṣipatha: 2nd PL of √kṣip ‘to throw’ –› ‘you throw’\n7\\) snihyataḥ: 3rd DU of √snih ‘to be attached to’ –› ‘they both are attached to’\n8\\) muñcathaḥ: 2nd DU of √muc ‘to release’ –› ‘you both release’\n9\\) bharāmi: 1st SG of √bhṛ ‘to carry’ –› ‘I carry’\n10\\) hṛṣyatha: 2nd PL of √hṛṣ ‘to be happy’ –› ‘you are happy’\n11\\) kṣipataḥ: 3rd DU of √kṣip ‘to throw’ –› ‘they both throw’\n12\\) viśāmaḥ: 1st PL of √viś ‘to enter’ –› ‘we enter’\n13\\) lumpanti: 3rd PL of √lup ‘to rob’ –› ‘they rob’\n14\\) vindāvaḥ: 1st DU of √vid ‘to find’ –› ‘we both find’\n15\\) snihyāmaḥ: 1st PL of √snih ‘to be attached to’ –› ‘we are attached to’\n16\\) paśyatha: 2nd PL of √dṛś ‘to see’ –› ‘you see’\n18\\) smarāvaḥ: 1st DU of √smṛ ‘to remember’ –› ‘we both remember’\n19\\) likhatha: 2nd PL of √likh ‘to write’ –› ‘you write’\n20\\) paśyasi: 2nd SG of √dṛś ‘to see’ –› ‘you see’\n\n3\\)\n1\\) I find [it] and I am happy.\n2\\) Do you carry [it] or does he carry [it]?\n3\\) I love, but you don’t love.\n4\\) Why do the two of them enter here?\n5\\) But you don’t understand.\n6\\) We both enter here and you both enter there.\n7\\) Do you remember again?\n8\\) I enter, but you don’t see [it/me].\n9\\) We enter. Why don’t you see [us]?\n\n4\\)\na\\) harāmaḥ\nb\\) punar gacchati\nc\\) hṛṣyathaḥ\nd\\) bodhāmi\ne\\) smarāmaḥ bodhāmaḥ ca\nf\\) tatra gacchanti atra ca na viśanti\ng\\) api bodhasi\nh\\) na paśyāvaḥ\ni\\) kiṃ paśyataḥ\nj\\) likhati\nk\\) likhati\nl\\) likhati\n", "Catalog/Sanskrit-Study/The Cambridge Introduction to Sanskrit - Answers to Chapter 4 Exercises.md": "---\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 4 Exercises\"\nsubtitle: \"\"\nauthor:\n  - Antonia M. Ruppel\neditor: []\ntranslator: []\nyear:\npublisher: \"\"\nseries: \"\"\nvolume: \"\"\ncontainer: \"\"\nsubject:\n  - Sanskrit-Study\ntype: other\nlanguage:\n  - Sanskrit\n  - English\npages: 1\ntext: searchable\nprint: false\nfiles:\n  - \"[[Chapter_4.pdf]]\"\n  - \"[[CIS - Answers to Chapter 4 Exercises (Ruppel)]]\"\naliases: []\n---\n\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 4 Exercises\n\n```dataviewjs\nawait dv.view(\"Templates/Views/open-pdf\")\n```\n\n**Checked against the file** on 10 November 2026.\n\nAnswer key to the Chapter 4 exercises; belongs with [[The Cambridge Introduction 11 - Chapter 4 The Present Tense|Chapter 4]].\n", "Study/Sanskrit/CIS - Answers to Chapter 5 Exercises (Ruppel).md": "---\ntype: other\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 5 Exercises\"\nauthor:\n  - Antonia M. Ruppel\nwork: \"[[The Cambridge Introduction to Sanskrit - Answers to Chapter 5 Exercises]]\"\nsource_pdf: Library/Sanskrit/Chapter_5.pdf\npage_range: \"1\"\npdf_pages: 1–1\ntext_source: PDF text layer (born-digital), PyMuPDF; Devanagari the text layer garbles rebuilt from the printed transliteration or read from the page image\nconverted: 2026-11-10\n---\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 5 Exercises\n\nAntonia M. Ruppel.\n\nConverted from the PDF on 10 Nov 2026. Each PDF page starts with `*[p. N]*`, the printed page number (or the PDF page where none is printed), ending in the block id `^pgK` for PDF page K. The PDF stays on the computer: open it from [[The Cambridge Introduction to Sanskrit - Answers to Chapter 5 Exercises|the catalog note]].\n\n> [!note] Devanagari\n> The PDF's text layer garbles most of the Devanagari. It is rebuilt here from the printed transliteration; check it against the PDF when it matters.\n\n*[p. 1]* ^pg1\n\nCHAPTER 5\n\n1\\) The Alarming Spread of Poetry\n\nTo the thinking man: DAT; few things: NOM; In the good old days: LOC; for the purpose: DAT; from the offices: ABL; of magazines and papers: GEN; to which: DAT (indirect object) or ACC (direction); their wares: ACC (direct object); a book: ACC (direct object); by a guarantee: INSTR; wine NOM; of cheese GEN.\n\nEditors: NOM; real money: ACC; for poetry: DAT; a profit: ACC; of verse: GEN; he: NOM; on a crust: LOC, or perhaps better INSTR (‘on’ here = ‘by means of’); the restaurant: NOM; a marked effect: ACC; to adolescence: ACC (direction); with the feeling: INSTR; poets: NOM (‘they’ = subject; ‘poets’ refers to ‘they’); by the heady knowledge: INSTR; all over the country: LOC; on a sunny afternoon: LOC; by the warm weather: INSTR; a horrible sight: NOM; at desks: LOC; Dear Sir: VOC; In reply: good question! LOC? INSTR (‘by means of…’)? NOM (‘as a reply’)?; with their fingers: INSTR; in their hair: LOC; with the agony: INSTR; rhymes: ACC. \n\nThe Jabberwocky the slithy toves: NOM; in the wabe: LOC; raths: NOM; my son: VOC; vorpal sword: ACC; in hand: LOC or INSTR; the manxome foe: ACC; by the Tumtum tree: LOC; in thought: LOC; in uffish thought: LOC; with eyes: INSTR; of flame: GEN; the vorpal blade: NOM; it: ACC; dead: ACC; with its head: INSTR; he: NOM; the Jabberwock: ACC; to my arms: ACC (direction); beamish boy: VOC; frabjous: VOC; in his joy: LOC; mimsy: NOM; the borogoves: NOM.\n\n2\\)\n1\\) bālaḥ aśvaṃ muñcati. (ACC) ‘The child releases [his] horse.’\n2\\) evam naraḥ bālaṃ pure vindati. (ACC, LOC) ‘Thus the man finds [his] child in the city.’\n3\\) bālaḥ eva aśvena saha puraṃ prati gacchati. (INSTR) ‘The child indeed/Only the child/The child alone/The child (implied: and not someone else) goes to the city with the [or: his] horse.’\n4\\) kiṃ grāmaṃ prati bharanti. (ACC) ‘What do they carry to the village?’\n5\\) narāḥ gṛhaṃ viśanti. (NOM PL, ACC) ‘The men enter the house.’\n6\\) siṃhaḥ vyāghraḥ ca narasya gṛhaṃ prati gacchataḥ. (GEN) ‘The lion and the tiger both go to the man’s house.’\n7\\) grāmāt naraḥ bālaḥ ca puraṃ prati gacchataḥ. (ABL, ACC) ‘The man and [his] child both go from the village to the city.’\n8\\) naraḥ bāle snihyati. (LOC) ‘The man is attached to/loves [his] child.’\n9\\) api siṃhaḥ kṣetrāt vanaṃ prati gacchati. (ABL, ACC) ‘Does the lion go/is the lion going from the field to the forest?’\n10\\) bālaḥ aśvena vinā grāmaṃ viśati. (INSTR) ‘The child enters the village without the[/his] horse.’\n\n3\\)\n1\\) तत्र/tatra\n2\\) ‘to carry’\n3\\) स्मृ/smṛ\n4\\) ‘lion’\n5\\) ‘what? why?’; marks sentence as a yes/no question\n6\\) मित्रम्/mitram\n7\\) ‘here’\n8\\) ‘he wants’\n9\\) ‘knowledge’\n10\\) ‘he sees’\n11\\) ‘to wake up; to understand’\n12\\) ‘warrior’\n13\\) मुञ्चति/muñcati\n14\\) ‘but’\n15\\) गच्छति/gacchati\n16\\) व्याघ्रः/vyāghraḥ\n17\\) ‘to rob’\n18\\) ‘or’\n\nREADING\n\nhanumad-vacanāt eva sugrīveṇa samāgataḥ mahā-balaḥ rāmaḥ sugrīvāya sarvam tat aśaṃsat । tataḥ vānara-rājena sarvam vaira-anukathanam prati rāmāya āveditam ।\n", "Catalog/Sanskrit-Study/The Cambridge Introduction to Sanskrit - Answers to Chapter 5 Exercises.md": "---\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 5 Exercises\"\nsubtitle: \"\"\nauthor:\n  - Antonia M. Ruppel\neditor: []\ntranslator: []\nyear:\npublisher: \"\"\nseries: \"\"\nvolume: \"\"\ncontainer: \"\"\nsubject:\n  - Sanskrit-Study\ntype: other\nlanguage:\n  - Sanskrit\n  - English\npages: 1\ntext: searchable\nprint: false\nfiles:\n  - \"[[Chapter_5.pdf]]\"\n  - \"[[CIS - Answers to Chapter 5 Exercises (Ruppel)]]\"\naliases: []\n---\n\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 5 Exercises\n\n```dataviewjs\nawait dv.view(\"Templates/Views/open-pdf\")\n```\n\n**Checked against the file** on 10 November 2026.\n\nAnswer key to the Chapter 5 exercises; belongs with [[The Cambridge Introduction 12 - Chapter 5 Road Map Nominals|Chapter 5]].\n", "Study/Sanskrit/CIS - Answers to Chapter 6 Exercises (Ruppel).md": "---\ntype: other\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 6 Exercises\"\nauthor:\n  - Antonia M. Ruppel\nwork: \"[[The Cambridge Introduction to Sanskrit - Answers to Chapter 6 Exercises]]\"\nsource_pdf: Library/Sanskrit/Chapter_6.pdf\npage_range: \"1\"\npdf_pages: 1–1\ntext_source: PDF text layer (born-digital), PyMuPDF; Devanagari the text layer garbles rebuilt from the printed transliteration or read from the page image\nconverted: 2026-11-10\n---\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 6 Exercises\n\nAntonia M. Ruppel.\n\nConverted from the PDF on 10 Nov 2026. Each PDF page starts with `*[p. N]*`, the printed page number (or the PDF page where none is printed), ending in the block id `^pgK` for PDF page K. The PDF stays on the computer: open it from [[The Cambridge Introduction to Sanskrit - Answers to Chapter 6 Exercises|the catalog note]].\n\n> [!note] Devanagari\n> The PDF's text layer garbles most of the Devanagari. It is rebuilt here from the printed transliteration; check it against the PDF when it matters.\n\n*[p. 1]* ^pg1\n\nCHAPTER 6\n\n1\\.\na\\) guṇaḥ, guṇa, guṇam, guṇena, guṇāya, guṇāt, guṇasya, guṇe\nb\\) ślokau, ślokau, ślokau, ślokābhyām, ślokābhyām, ślokābhyām, ślokayoḥ, ślokayoḥ\nc\\) dūtāḥ, dūtāḥ, dūtān, dūtaiḥ, dūtebhyaḥ, dūtebhyaḥ, dūtānām, dūteṣu\nd\\) phalāni, phalāni, phalāni, phalaiḥ, phalebhyaḥ, phalebhyaḥ, phalānām, phaleṣu\n\n2\\.\n1\\) puruṣeṇa: INSTR SG of puruṣa- –› ‘with a/the man’ (from now on, only one possible translation will be given; the choice of a/the depends on the context)\n2\\) dūta: VOC SG of dūta- –› ‘o messenger’\n3\\) yuddhe: LOC SG of yuddha- –› ‘in a fight’, NOMVOCACC DU of yuddha- –› ‘two fights, o two fights’\n4\\) nṛpāt: ABL SG of nṛpa- –› ‘from a leader’\n5\\) vedāya: DAT SG of veda- –› ‘for knowledge’\n6\\) kṣetrāṇi: NOMVOCACC PL of kṣetra- –› ‘fields’\n7\\) vyāghraiḥ: INSTR PL of vyāghra- –› ‘with tigers’\n8\\) vacaneṣu: LOC PL of vacana- –› ‘in speeches’\n9\\) śūrasya: GEN SG of śūra- –› ‘of a hero’\n10\\) bālān: ACC PL of bāla- –› ‘children’\n11\\) īśvaraḥ: NOM SG of īśvara- –› ‘the lord’\n12\\) guṇaiḥ: INSTR PL of guṇa- –› ‘with (good) qualities’\n13\\) phalena: INSTR SG of phala- –› ‘with a fruit/reward’\n14\\) sukhau narau: NOMVOCACC DU of sukha- nara- –› ‘two happy men’\n15\\) vanam: NOMACC SG of vana- –› ‘a forest’\n16\\) kṣatriyaiḥ: INSTR PL of kṣatriya- –› ‘by warriors’\n17\\) puruṣa: VOC SG of puruṣa- –› ‘man! servant!’\n18\\) janān: ACC PL of jana- –› ‘people’\n19\\) dharmāt: ABL SG of dharma- –› ‘from/out of duty’\n20\\) jñānena: INSTR SG of jñāna- –› ‘with wisdom’\n21\\) dūtam: ACC SG of dūta- –› ‘a messenger’\n22\\) ślokānām: GEN PL of śloka- –› ‘of verses’\n23\\) putrāṇām: GEN PL of putra- –› ‘of sons’\n24\\) mitrayoḥ: GENLOC DU of mitra- –› ‘of/in the two friends’\n25\\) gṛhāt: ABL SG of gṛha- –› ‘from the house’\n26\\) īśvarāya: DAT SG of īśvara- –› ‘for/to a lord’\n27\\) bālena priyeṇa: INSTR SG of bāla- priya- –› ‘with a dear/one’s own child’\n\n3\\.\na\\) ईश्वराणाम्/īśvarāṇām\nb\\) ज्ञानेन jñānena\nc\\) वने/vane\nd\\) सिंहम्/siṃham\ne\\) श्लोकेन/ślokena\nf\\) वचने/vacane\ng\\) सिंहः/siṃhaḥ\nh\\) पाप ईश्वर/pāpa īśvara\ni\\) पुरम्/puram\nj\\) फलाय/phalāya\nk\\) युद्धात्/yuddhāt\nl\\) क्षेत्रयोः/kṣetrayoḥ\nm\\) बालाः/bālāḥ\nn\\) गृहाभ्याम्/gṛhābhyām\no\\) पुरेषु or नगरेषु/pureṣu or nagareṣu\np\\) जनेभ्यः/janebhyaḥ\n\n4\\.\n1\\) We enter the master’s house/the house of the master.\n2\\) What is the child doing in the master’s house?\n3\\) The two children enter the forest with the[/their] horses.\n4\\) The children understand the man’s words and are excited.\n5\\) Master! What do you want?\n6\\) The child remembers the god’s (good) qualities.\n7\\) The two heroes carry their friend from the fight.\n8\\) ‘God [is] here in the forest’, the child understands.\n9\\) For a king, the people [are] dear like his children.\n10\\) Are the child’s friends heroic or bad/heroes or bad guys?\n11\\) The horse carries the man and [his] two children from the forest to the city.\n12\\) O heroic men, do you see the two lions in the forest?\n13\\) The child does not remember the friend’s/his friend’s words\n14\\) ‘The horses are excited from the fight,’ the hero understands.\n15\\) Do the man and [his] horse see the tigers?\n16\\) The masters take the evil men’s horses and rob their houses.\n17\\) In the tree indeed/only in the tree I see fruit.\n18\\) Here in the fight I see evil and heroic people.\n\nREADINGS\n\nThe order of life on earth\n‘Here/In this world there are creatures of two kinds: the moving and the stationary (ones). The moving creatures have a threefold origin (of the moving ones (there is) a threefold origin), [being] born from an egg, heat (‘sweat’) or a womb. Indeed, of all moving (ones), the best, o king, are womb-born ones. Of the womb-born ones the best are men and domestic animals.’\n\nThe best possible gift\n‘No gift of cows, no gift of earth/land or gift of food is indeed such an important thing as the greatest gift of/among all gifts: the gift of safety/of absence of fear.’\n", "Catalog/Sanskrit-Study/The Cambridge Introduction to Sanskrit - Answers to Chapter 6 Exercises.md": "---\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 6 Exercises\"\nsubtitle: \"\"\nauthor:\n  - Antonia M. Ruppel\neditor: []\ntranslator: []\nyear:\npublisher: \"\"\nseries: \"\"\nvolume: \"\"\ncontainer: \"\"\nsubject:\n  - Sanskrit-Study\ntype: other\nlanguage:\n  - Sanskrit\n  - English\npages: 1\ntext: searchable\nprint: false\nfiles:\n  - \"[[Chapter_6.pdf]]\"\n  - \"[[CIS - Answers to Chapter 6 Exercises (Ruppel)]]\"\naliases: []\n---\n\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 6 Exercises\n\n```dataviewjs\nawait dv.view(\"Templates/Views/open-pdf\")\n```\n\n**Checked against the file** on 10 November 2026.\n\nAnswer key to the Chapter 6 exercises; belongs with [[The Cambridge Introduction 13 - Chapter 6 a-stems|Chapter 6]].\n", "Study/Sanskrit/CIS - Answers to Chapter 7 Exercises (Ruppel).md": "---\ntype: other\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 7 Exercises\"\nauthor:\n  - Antonia M. Ruppel\nwork: \"[[The Cambridge Introduction to Sanskrit - Answers to Chapter 7 Exercises]]\"\nsource_pdf: Library/Sanskrit/Chapter_7.pdf\npage_range: \"1\"\npdf_pages: 1–1\ntext_source: PDF text layer (born-digital), PyMuPDF; Devanagari the text layer garbles rebuilt from the printed transliteration or read from the page image\nconverted: 2026-11-10\n---\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 7 Exercises\n\nAntonia M. Ruppel.\n\nConverted from the PDF on 10 Nov 2026. Each PDF page starts with `*[p. N]*`, the printed page number (or the PDF page where none is printed), ending in the block id `^pgK` for PDF page K. The PDF stays on the computer: open it from [[The Cambridge Introduction to Sanskrit - Answers to Chapter 7 Exercises|the catalog note]].\n\n> [!note] Devanagari\n> The PDF's text layer garbles most of the Devanagari. It is rebuilt here from the printed transliteration (in 4, from the roots and meanings given); check it against the PDF when it matters.\n\n*[p. 1]* ^pg1\n\nCHAPTER 7\n\n1\\) vadati, śocati (√vad is among the roots that are cited in guṇa – you can see that from the fact that the form ‘vad’ contains an -a-. Already standing in guṇa, this root does thus not add an -a- to form the present- tense stem. √śuc, on the other hand is cited in zero grade, thus needs to add an -a- to form its present- tense stem, and thus we arrive at śocati.\n\n2\\)\n1\\) कथयति/kathayati – ‘to talk about’\n2\\) यजति/yajati – ‘to worship’\n3\\) नयति/nayati – ‘to lead’\n4\\) इच्छति/icchati – ‘to want’\n5\\) स्निह्यति/snihyati – ‘to love, be attached to’\n6\\) शोचति śocati – ‘to mourn’\n7\\) पूजयति/pūjayati – ‘to honour’\n8\\) भवति/bhavati – ‘to be’\n9\\) क्षिपति/kṣipati – ‘to throw’\n10\\) मुञ्चति/muñcati – ‘to release’\n11\\) जयति/jayati – ‘to win’\n12\\) स्मरति/smarati – ‘to remember’\n13\\) पश्यति/paśyati– ‘to see’\n\n3\\)\n1\\) √bhū ‘to be’ –› guṇa: bho/bhav, vṛddhi: bhau/bhāv\n2\\) √budh ‘to understand’ –› guṇa: bodh, vṛddhi: baudh\n3\\) √kṛ ‘to do’ –› guṇa: kar, vṛddhi: kār\n4\\) √gam ‘to go’ –› zero: ga/gm, vṛddhi: gām\n5\\) √i ‘to go’ –› guṇa: e/ay, vṛddhi: ai/āy\n6\\) √kḷp ‘to be suitable’ –› guṇa: kalp, vṛddhi: kālp\n7\\) √bhī ‘to fear’ –› guṇa: bhe/bhay, vṛddhi: bhai/bhāy\n8\\) √man ‘to think’ –› zero: ma/mn, vṛddhi: mān\n9\\) √ji ‘to win’ –› guṇa: je/jay, vṛddhi: jai/jāy\n10\\) √pat ‘to fall’ –› zero: pt, vṛddhi: pāt\n11\\) √tyaj ‘to abandon’ –› zero: tij, vṛddhi: tyāj\n12\\) √svap ‘to sleep’ –› zero: sup, vṛddhi: svāp\n\n4\\) (To keep this from being just a formal exercise, the answers below include the meaning of each word.)\n1\\) vṛddhi, √bhṛ; भारः –› ‘burden, load’; ‘work, toil’\n2\\) guṇa, √hṛṣ; हर्षः –› ‘joy, pleasure, happiness’\n3\\) guṇa, √likh; लेखः –› ‘line, stroke’; pl. ‘letter, writing’\n4\\) guṇa, √kṣip; क्षेपः –› ‘a throw, throwing’\n5\\) zero, √smṛ; स्मृतिः –› ‘memory, remembrance’\n6\\) zero, √nam; नतिः –› ‘bending, bowing; humility, modesty’\n7\\) vṛddhi, √pat; पातः –› ‘flight; falling, downfall’\n8\\) zero, √cint; चिन्ता –› ‘worry’\n9\\) guṇa, √ji; जेता –› ‘a winner, victor’\n10\\) vṛddhi, √tyaj; त्यागः –› ‘leaving, abandoning’\n11\\) guṇa, √dṛś; दर्शनम् –› ‘sight; appearance’\n12\\) guṇa, √snih; स्नेहः –› ‘love, attachment to’\n13\\) guṇa, √śuc; शोकः –› ‘grief’\n14\\) guṇa, √nam; नमः –› ‘a bow, a greeting’\n15\\) guṇa, √nī; नेता –› ‘a leader’\n16\\) vṛddhi, √bhū; प्रभावः –› ‘might, power’ (lit. ‘before-being’)\n17\\) guṇa, √dru; द्रवः –› ‘motion, (quick) movement’\n\n5\\)\na\\) शोचयति/śocayati\nb\\) नाययति/nāyayati\nc\\) स्नेहयति/snehayati\nd\\) हारयति/hārayati\ne\\) द्रावयति/drāvayati\nf\\) स्थापयति/sthāpayati\ng\\) वर्धयति/vardhayati (Note: even though -a- is a short vowel, the syllable as a whole counts as long because its vowel is followed by more than one consonant – see Chapter 2a.)\n\n6\\)\n1\\) ‘they grieve’\n2\\) ‘you (pl.) carry’\n3\\) ‘he stands’\n4\\) ‘you both are excited’\n5\\) ‘the two of us/we both honour’\n6\\) ‘I understand’\n7\\) ‘he does’\n8\\) द्रावयन्ति/drāvayanti\n9\\) ‘you write’\n10\\) ‘you (pl.) tell’\n11\\) ‘we want’\n12\\) ‘they both remember’\n13\\) ‘they abandon’\n14\\) पश्यामि/paśyāmi\n15\\) ‘you take’\n16\\) नमसि/namasi\n17\\) ‘I enter’\n18\\) ‘he is’\n19\\) ‘the two of you make [someone] carry [something]\n20\\) ‘you cause [someone] to enter’\n\n7\\)\n1\\) We leave our own house and lead the horses to the city.\n2\\) Friend! Do you honour the gods with words and verses?\n3\\) The masters cause the city to grow/make the city bigger.\n4\\) Children, why are you standing here and are not in the house? (Addressing two children.)\n5\\) The child runs [away] from the house with his friend.\n6\\) The mighty men cause the tiger to run to the forest.\n7\\) Do the warriors cause the evil men to fall in the fight?\n8\\) The brave horse protects/saves the man from the tiger.\n9\\) I remember my friends, at least, and lead them to the house.\n10\\) Oh, warriors! Are you defeating the evil man in the battle and leading the people to the city?\n\nREADINGS\n\nLike father, like son\nNecessarily the son follows the father’s conduct. For indeed an Āmalakī fruit does not come from/of a Ketaka tree.\n\nThe natural circle of things\nCreatures/living beings come from food, the origin of the food is from rain, rain comes from ritual sacrifice.\n", "Catalog/Sanskrit-Study/The Cambridge Introduction to Sanskrit - Answers to Chapter 7 Exercises.md": "---\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 7 Exercises\"\nsubtitle: \"\"\nauthor:\n  - Antonia M. Ruppel\neditor: []\ntranslator: []\nyear:\npublisher: \"\"\nseries: \"\"\nvolume: \"\"\ncontainer: \"\"\nsubject:\n  - Sanskrit-Study\ntype: other\nlanguage:\n  - Sanskrit\n  - English\npages: 1\ntext: searchable\nprint: false\nfiles:\n  - \"[[Chapter_7.pdf]]\"\n  - \"[[CIS - Answers to Chapter 7 Exercises (Ruppel)]]\"\naliases: []\n---\n\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 7 Exercises\n\n```dataviewjs\nawait dv.view(\"Templates/Views/open-pdf\")\n```\n\n**Checked against the file** on 10 November 2026.\n\nAnswer key to the Chapter 7 exercises; belongs with [[The Cambridge Introduction 14 - Chapter 7 Vowel Gradation and Why We Need to Know about It|Chapter 7]].\n", "Study/Sanskrit/CIS - Answers to Chapter 8 Exercises (Ruppel).md": "---\ntype: other\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 8 Exercises\"\nauthor:\n  - Antonia M. Ruppel\nwork: \"[[The Cambridge Introduction to Sanskrit - Answers to Chapter 8 Exercises]]\"\nsource_pdf: Library/Sanskrit/Chapter_8.pdf\npage_range: \"1-2\"\npdf_pages: 1–2\ntext_source: PDF text layer (born-digital), PyMuPDF; Devanagari the text layer garbles rebuilt from the printed transliteration or read from the page image\nconverted: 2026-11-10\n---\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 8 Exercises\n\nAntonia M. Ruppel.\n\nConverted from the PDF on 10 Nov 2026. Each PDF page starts with `*[p. N]*`, the printed page number (or the PDF page where none is printed), ending in the block id `^pgK` for PDF page K. The PDF stays on the computer: open it from [[The Cambridge Introduction to Sanskrit - Answers to Chapter 8 Exercises|the catalog note]].\n\n> [!note] Devanagari\n> The PDF's text layer garbles most of the Devanagari. It is rebuilt here from the printed transliteration; check it against the PDF when it matters.\n\n*[p. 1]* ^pg1\n\nCHAPTER 8\n\n1\\.\n1\\) patitvā: absolutive of √pat –› ‘having fallen’\n2\\) kṣipitaḥ vṛkṣaḥ: NOM SG MASC of the ta-participle of √kṣip and of vṛkṣa- –› ‘the tree that was hit’\n3\\) nītānām bālānām: GEN PL MASC of the ta-participle of √nī and of bāla- –› ‘of the children that have been led’\n4\\) namitum: infinitive of √nam –› ‘to bend, bow’\n5\\) snigdhebhyaḥ mitrebhyaḥ: DATABL PL NTR of the ta-participle of √snih and of mitra- –› ‘for/from the friends who are loved’\n6\\) pālayitvā: absolutive of √pāl –› ‘having protected’\n7\\) uktasya vacanasya: GEN SG NTR of the ta-participle of √vac and of vacana- –› ‘of the word that was said’\n8\\) tyaktvā: absolutive of √tyaj –› ‘having abandoned’\n9\\) iṣṭāḥ aśvāḥ: NOMVOC PL MASC of the ta-participle of √iṣ and of aśva- –› ‘the wanted/desired horses’\n10\\) gatvā: absolutive of √gam –› ‘having gone’\n11\\) śoktum: infinitive of √śuc –› ‘to mourn’\n12\\) bhūtvā: absolutive of √bhū –› ‘having been/become’\n13\\) jetum: infinitve of √ji –› ‘to win’\n14\\) kathayitvā: absolutive of √kath –› ‘having told’\n15\\) dagdhaḥ grāmaḥ: NOM SG MASC of the ta-participle of √dah and of grāma- –› ‘the burnt village’\n16\\) harṣṭum: infinitive of √hṛṣ –› ‘to be excited’\n17\\) cintayitvā: absolutive of √cint –› ‘having worried about’\n18\\) dagdhum: infinitive of √dah –› ‘to burn’\n19\\) buddhvā: absolutive of √budh –› ‘having understood’\n20\\) viṣṭena gṛheṇa: INSTR SG MASC/NTR of the ta- participle of √viś and of gṛha- –› ‘by/with the house that had been entered’\n21\\) dhārayitum: infinitive of √dhṛ –› ‘to hold’\n22\\) tyaktāt purāt: ABL SG NTR of the ta-participle of √tyaj and of pura- –› ‘from the abandoned city’\n\n2\\.\na\\) भृत्वा, भृतः (bhṛtvā, bhṛtaḥ)\nb\\) लिखित्वा, लिखितः (likhitvā, likhitaḥ)\nc\\) द्रुत्वा, द्रुतः (drutvā, drutaḥ)\nd\\) मुक्त्वा, मुक्तः (muktvā, muktaḥ)\ne\\) वृद्ध्वा, वृद्धः (vṛddhvā, vṛddhaḥ)\nf\\) नत्वा, नतः (natvā, nataḥ)\ng\\) जीवित्वा, जीवितः (jīvitvā, jīvitaḥ)\nh\\) नीत्वा, नीतः (nītvā, nītaḥ)\ni\\) स्मृत्वा, स्मृतः (smṛtvā, smṛtaḥ)\n\n3\\.\n1\\) ‘the fields’\n2\\) ‘they enjoy’\n3\\) ‘of the verses’\n4\\) ‘the one who was caused/made to bow’\n5\\) ‘to release’\n6\\) ‘they both perish’\n7\\) ‘they cause to lead’\n8\\) ‘in the fights’\n9\\) ‘of/in the two friends’\n10\\) ‘having been protected’\n11\\) ‘they two protect’\n12\\) ‘he protects’\n13\\) ‘by those who were bent/bowed to’\n14\\) ‘having been caused to mourn’\n15\\) ‘with/for/from the two houses’\n16\\) ‘having seen’\n17\\) ‘we cause to see/we show’\n18\\) ‘to burn’\n19\\) ‘you speak/say’\n20\\) ‘you two want’\n21\\) ‘you go’\n\n4\\.\n1\\) Having defeated the evil men in the fight, the heroes are happy.\n2\\) I see your friends (who are) standing in the village.\n3\\) Having protected the child from the tiger, the horse goes with the child to the master's house.\n4\\) Having wondered “What is the lion doing here?”, the child runs to the house.\n5\\) Having left behind his own family, the prince leads his friends to the fight.\n6\\) The messenger went to the forest. “Why are you going there?”, he was asked by the man.\n7\\) Having left the house with his two friends, the child runs from the city to the forest.\n8\\) The stories of the city conquered by the heroes make the people happy. The people bow to the heroes.\n9\\) Having said: “I live in the city”, the child asks the man: “Why do you live in the forest?”\n10\\) We say: “The gods see [our] good qualities.”\n11\\) Having gone to their master’s house, did the people bow to the master?\n12\\) Having said “I do not want to leave my house and family”, the young man sits down.\n13\\) Having said: “We are going to see [our] friends”, the children leave the house.\n14\\) Having seen the city conquered by evil men, the heroes do not want to enter it/that city.\n15\\) The son, having taken the fruit that have fallen from the tree, wants to give them to [his] master.\n16\\) The son, having taken the fruit that have been made to fall from the tree (that were shaken off the tree) by the man, wants to give them to [his] master.\n17\\) I do not want to go to the forest. 18) Having seen the burnt field and the abandoned city here, the people mourn.\n\nREADINGS\n\nKṛṣṇa tells Arjuna about the cycle of rebirths\nMany of my births have passed and many of yours, Arjuna. I know them all, but you do not know [them], burner of the enemy\n\nWays to learn about someone's character\nHaving seen the messenger or the letter of a leader whom I haven’t seen, I know if that leader is wise or without wisdom.\n\nA warrior’s fortune\nEither, having been killed, he will reach heaven, or, having killed his enemies, [he will\n\n*[p. 2]* ^pg2\n\nreach] happiness. Both these qualities of heroes are very difficult to attain.\n", "Catalog/Sanskrit-Study/The Cambridge Introduction to Sanskrit - Answers to Chapter 8 Exercises.md": "---\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 8 Exercises\"\nsubtitle: \"\"\nauthor:\n  - Antonia M. Ruppel\neditor: []\ntranslator: []\nyear:\npublisher: \"\"\nseries: \"\"\nvolume: \"\"\ncontainer: \"\"\nsubject:\n  - Sanskrit-Study\ntype: other\nlanguage:\n  - Sanskrit\n  - English\npages: 2\ntext: searchable\nprint: false\nfiles:\n  - \"[[Chapter_8.pdf]]\"\n  - \"[[CIS - Answers to Chapter 8 Exercises (Ruppel)]]\"\naliases: []\n---\n\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 8 Exercises\n\n```dataviewjs\nawait dv.view(\"Templates/Views/open-pdf\")\n```\n\n**Checked against the file** on 10 November 2026.\n\nAnswer key to the Chapter 8 exercises; belongs with [[The Cambridge Introduction 15 - Chapter 8 Absolutives, ta-participles and Infinitives; Introduction|Chapter 8]].\n", "Study/Sanskrit/CIS - Answers to Chapter 9 Exercises (Ruppel).md": "---\ntype: other\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 9 Exercises\"\nauthor:\n  - Antonia M. Ruppel\nwork: \"[[The Cambridge Introduction to Sanskrit - Answers to Chapter 9 Exercises]]\"\nsource_pdf: Library/Sanskrit/Chapter_9.pdf\npage_range: \"1\"\npdf_pages: 1–1\ntext_source: PDF text layer (born-digital), PyMuPDF; Devanagari the text layer garbles rebuilt from the printed transliteration or read from the page image\nconverted: 2026-11-10\n---\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 9 Exercises\n\nAntonia M. Ruppel.\n\nConverted from the PDF on 10 Nov 2026. Each PDF page starts with `*[p. N]*`, the printed page number (or the PDF page where none is printed), ending in the block id `^pgK` for PDF page K. The PDF stays on the computer: open it from [[The Cambridge Introduction to Sanskrit - Answers to Chapter 9 Exercises|the catalog note]].\n\n*[p. 1]* ^pg1\n\nCHAPTER 9\n\n1\\.\n1\\) prajāyai: DAT SG of prajā- (f.) ‘progeny’ –› ‘for/to the progeny’\n2\\) kathāsu: LOC PL of kathā- (f.) ‘story’ –› ‘in the stories’\n3\\) ugrābhiḥ: INSTR PL FEM of ugra- ‘terrible’ –› ‘by/with terrible [women/grammatically feminine ones]’\n4\\) priye: LOC SG MASC of priya- ‘one’s own, dear’ –› ‘in one’s own, in a dear…’; VOC SG FEM, NOMVOCACC DU FEM –› ‘dear!’, ‘(o) dear ones’ (addressing one/two women or girls, or anything else that is grammatically feminine), NOMVOCACC DU NTR ‘(o) dear ones’ (addressing/talking about exactly two)\n5\\) prabhāyāḥ: ABLGENSg of prabhā- (f.) ‘splendor’ –› ‘from/of splendor’\n6\\) chāyāyām: LOC SG of chāyā- (f.) ‘shadow, shade’ –› ‘in the shade’\n7\\) amarāḥ: NOMVOCACC PL FEM/NOMVOC PL MASC of amara- ‘immortal –› ‘the/o immortal ones’\n8\\) prajayā: INSTR SG of prajā- (f.) ‘progeny’ –› ‘with/by the progeny/offspring’\n9\\) priyā: NOM SG FEM of priya- ‘one’s own’ –› ‘one’s own’\n10\\) prajñā: Nom Sg of prajñā- (f.) ‘wisdom’ –› ‘wisdom’\n11\\) prājñā: Nom Sg Fem of prājña- ‘wise’ –› ‘the wise woman’\n12\\) bhāryāyai: DAT SG of bhāryā- (f.) ‘wife’ –› ‘for/to the (his) wife’\n13\\) pūjā: NOM SG of pūjā- (f.) ‘honour’ –› ‘honour’\n14\\) jarām: ACC SG of jarā- (f.) ‘old age’–› ‘old age’\n15\\) cintāḥ: NOMVOCACC PL of cintā- (f.) ‘care, worry’ –› ‘cares, worries’\n16\\) āśāyām: LOC SG of āśā- (f.) ‘hope’ –› ‘in hope’\n17\\) āśayā: INSTR SG of āśā- (f.) ‘hope’ –› ‘with hope’\n18\\) māyām: ACC SG of māyā- (f.) ‘magic, illusion’ –› ‘magic, illusion’\n19\\) prajāyāḥ: ABLGEN SG of prajā- (f.) ‘progeny’ –› ‘from/of the progeny’\n20\\) bāle: VOC SG and NOMVOCACC DU of bālā- (f.) ‘girl’–› ‘girl!’; ‘two girls, o girls!’\n21\\) pṛtanābhyaḥ: DATABL PL of pṛtanā- (f.) ‘battle’ –› ‘for/from the battles’\n22\\) kanyayoḥ: GENLOC DU of kanyā- (f.) ‘girl’ –› ‘of/in the two girls’\n23\\) pāpayoḥ: GENLOC DU MASC/FEM/NTR of papa- ‘evil’ –› ‘of/in both evil men/women/things’\n24\\) śūrām: ACC SG FEM of śūra- ‘mighty’ –› ‘the mighty woman’\n\n2\\.\na\\) kathābhyām\nb\\) jarāyāḥ\nc\\) prajāyai\nd\\) chāyāḥ\ne\\) kanyayoḥ\nf\\) māyayā\ng\\) bhārye\nh\\) kanyābhyaḥ\ni\\) pūjāyāḥ\nj\\) cintābhyaḥ\nk\\) prabhām\nl\\) pṛtanāsu, yuddheṣu\nm\\) senābhiḥ\nn\\) āśāḥ\no\\) prajñāyāḥ\n\n3\\.\na\\) NOMVOCACC: ugrau vyāghrau, INSTRDATABL: ugrābhyām vyāghrābhyām, GENLOC: ugrayoḥ vyāghrayoḥ\nb\\) NOMVOCACC: priyāṇi mitrāṇi, INSTR priyaiḥ mitraiḥ, DATABL priyebhyaḥ mitrebhyaḥ, GEN priyāṇām mitrāṇām, LOC priyeṣu mitreṣu\nc\\) NOM śūrā bālā, VOC śūre bāle, ACC śūrām bālām, INSTR śūrayā bālayā, DAT śūrāyai bālāyai, ABLGEN śūrāyāḥ bālāyāḥ, LOC śūrāyām bālāyām \n\n4\\.\n1\\) Having seen his wife and daughters (or: children), the man, pleased, goes into the city.\n2\\) Having said: ‘Honour to the immortals!’, the people bow.\n3\\) There are worries in fights and battles.\n4\\) Having heard the stories of the gods, the two men go to the tree standing in the field and sit down.\n5\\) ‘There is wisdom in old age’, the child says.\n6\\) The master is the protector of (his) subjects.\n7\\) Having seen the beauty of the girl the prince forgets his worries.\n8\\) Having heard the story of/about the bad people defeated by the heroes, do you honour these heroes?\n9\\) The man thinks: ‘The girl is grown(-up).’\n10\\) Like a wise god, he/she lives happily.\n\nSītā’s abductor talks about her and her husband, Rāma\nShe was abducted by me, his wife, called Sītā, Janaka’s daughter. Rāma/he has come here, having constructed a bridge over the ocean, wanting to/intent on freeing her.\n\nAdvice for politicians\nIt is not possible to rule a kingdom with the natural standards of men, for those which are faults of men are the good qualities of a ruler. \n\nAsk yourself where you are in life\nAsk yourself again and again: what is the right time? Who are (my) friends? Which place (is this)? What changes (are these)? Who am I and what is my strength?\n", "Catalog/Sanskrit-Study/The Cambridge Introduction to Sanskrit - Answers to Chapter 9 Exercises.md": "---\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 9 Exercises\"\nsubtitle: \"\"\nauthor:\n  - Antonia M. Ruppel\neditor: []\ntranslator: []\nyear:\npublisher: \"\"\nseries: \"\"\nvolume: \"\"\ncontainer: \"\"\nsubject:\n  - Sanskrit-Study\ntype: other\nlanguage:\n  - Sanskrit\n  - English\npages: 1\ntext: searchable\nprint: false\nfiles:\n  - \"[[Chapter_9.pdf]]\"\n  - \"[[CIS - Answers to Chapter 9 Exercises (Ruppel)]]\"\naliases: []\n---\n\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 9 Exercises\n\n```dataviewjs\nawait dv.view(\"Templates/Views/open-pdf\")\n```\n\n**Checked against the file** on 10 November 2026.\n\nAnswer key to the Chapter 9 exercises; belongs with [[The Cambridge Introduction 16 - Chapter 9 a-stems|Chapter 9]].\n", "Study/Sanskrit/CIS - Answers to Chapter 10 Exercises (Ruppel).md": "---\ntype: other\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 10 Exercises\"\nauthor:\n  - Antonia M. Ruppel\nwork: \"[[The Cambridge Introduction to Sanskrit - Answers to Chapter 10 Exercises]]\"\nsource_pdf: Library/Sanskrit/Chapter_10.pdf\npage_range: \"1\"\npdf_pages: 1–1\ntext_source: PDF text layer (born-digital), PyMuPDF; Devanagari the text layer garbles rebuilt from the printed transliteration or read from the page image\nconverted: 2026-11-10\n---\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 10 Exercises\n\nAntonia M. Ruppel.\n\nConverted from the PDF on 10 Nov 2026. Each PDF page starts with `*[p. N]*`, the printed page number (or the PDF page where none is printed), ending in the block id `^pgK` for PDF page K. The PDF stays on the computer: open it from [[The Cambridge Introduction to Sanskrit - Answers to Chapter 10 Exercises|the catalog note]].\n\n> [!note] Devanagari\n> The PDF's text layer garbles most of the Devanagari. It is rebuilt here from the printed transliteration (the words in 1 have none, so they were read from the page image); check it against the PDF when it matters.\n\n*[p. 1]* ^pg1\n\nCHAPTER 10\n\n1\\.\n१\\) संभरथ –› sam- + √bhṛ\n२\\) समूत्पतामः –› sam- + ud- + √pat\n३\\) उद्धारयसि –› ud- + √dhṛ\n४\\) अनुविनशामः –› anu- + vi- + √naś\n५\\) व्यपनयन्ति –› vi- + apa- + √nī\n६\\) अध्यागम्य –› adhi- + ā- + √gam\n७\\) विषीदति –› vi- + √sad\n८\\) संनिभृतम् –› sam- + ni- + √bhṛ\n९\\) परिणमति –› pari- + √nam\n१०\\) प्रोद्भवसि –› pra- + ud- + √bhū\n११\\) उपानेतुम् –› upa- + ā- + √nī\n१२\\) व्यपगच्छथ –› vi- + apa- + √gam\n१३\\) प्रणत्य –› pra- + √nam\n१४\\) पर्यन्विच्छामः –› pari- + anu- + √iṣ\n१५\\) प्रतीष्टः –› prati- + √iṣ\n\n2\\)\n1\\) The people go apart/split up. The men go into the field and the boys into the house.\n2\\) The men, wives and children praise the gods together with their verses.\n3\\) From/because of the tiger, the children together with their horses run to the house/run home, and the birds fly up.\n4\\) Having bowed to the master, the young men stand up together.\n5\\) The wise ruler foresees the worries of the subjects.\n6\\) The warrior does not survive (‘over-live’) and the people mourn him.\n7\\) Having listened to the master’s words the two girls come/approach.\n8\\) Having forgotten her own worries, the girl stands/gets up and goes back to the city.\n9\\) Having all led the horses from the fields, we sit in the house/at home and tell stories.\n10\\) The people mourn the child that had been robbed/seized by a tiger.\n11\\) Having gone away from/left the house, the two girls run towards the fields.\n\nREADINGS\n\nRāma takes back Sītā\nRāma takes her (Sītā) back, relying on the force/army of Sugrīva, having built (literally: bound) a bridge across the ocean and burnt Lankā with sharp arrows.\n\nIntroducing the story of the foolish turtle\nHe who does not welcome the advice of loyally loving friends, he perishes (will perish) like the foolish turtle that had fallen from a log.\n\nThe effect of choosing bad leaders\nHaving appointed a king of imperfect character and intent on bad conduct, countries and cities will perish, entered (overcome) by bad conduct. \n\nKṛṣṇa/Viṣṇu describes himself\nI am the fluidity in the waters, Arjuna, I am the light of the moon and the sun. I am the om in all the Vedas, I am the sound of/in the sky, I am humanity in men.\n", "Catalog/Sanskrit-Study/The Cambridge Introduction to Sanskrit - Answers to Chapter 10 Exercises.md": "---\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 10 Exercises\"\nsubtitle: \"\"\nauthor:\n  - Antonia M. Ruppel\neditor: []\ntranslator: []\nyear:\npublisher: \"\"\nseries: \"\"\nvolume: \"\"\ncontainer: \"\"\nsubject:\n  - Sanskrit-Study\ntype: other\nlanguage:\n  - Sanskrit\n  - English\npages: 1\ntext: searchable\nprint: false\nfiles:\n  - \"[[Chapter_10.pdf]]\"\n  - \"[[CIS - Answers to Chapter 10 Exercises (Ruppel)]]\"\naliases: []\n---\n\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 10 Exercises\n\n```dataviewjs\nawait dv.view(\"Templates/Views/open-pdf\")\n```\n\n**Checked against the file** on 10 November 2026.\n\nAnswer key to the Chapter 10 exercises; belongs with [[The Cambridge Introduction 17 - Chapter 10 Prepositions and Preverbs|Chapter 10]].\n", "Study/Sanskrit/CIS - Answers to Chapter 11 Exercises (Ruppel).md": "---\ntype: other\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 11 Exercises\"\nauthor:\n  - Antonia M. Ruppel\nwork: \"[[The Cambridge Introduction to Sanskrit - Answers to Chapter 11 Exercises]]\"\nsource_pdf: Library/Sanskrit/Chapter_11.pdf\npage_range: \"1\"\npdf_pages: 1–1\ntext_source: PDF text layer (born-digital), PyMuPDF; Devanagari the text layer garbles rebuilt from the printed transliteration or read from the page image\nconverted: 2026-11-10\n---\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 11 Exercises\n\nAntonia M. Ruppel.\n\nConverted from the PDF on 10 Nov 2026. Each PDF page starts with `*[p. N]*`, the printed page number (or the PDF page where none is printed), ending in the block id `^pgK` for PDF page K. The PDF stays on the computer: open it from [[The Cambridge Introduction to Sanskrit - Answers to Chapter 11 Exercises|the catalog note]].\n\n> [!note] Devanagari\n> The PDF's text layer garbles most of the Devanagari. It is rebuilt here from the printed transliteration; check it against the PDF when it matters.\n\n> [!note] Item 1m\n> The PDF prints a missing-glyph box here; it is read as ḷ.\n\n*[p. 1]* ^pg1\n\nCHAPTER 11\n\n1\\.\na\\) -da-\nb\\) -gdh-\nc\\) -ñj-\nd\\) -ṅn-\ne\\) - mi-\nf\\) -cch-\ng\\) -āna-\nh\\) -ṃ t-\ni\\) -ggh-\nj\\) -tt-\nk\\) -mn-\nl\\) -gl-\nm\\) -ḷ -\nn\\) -ddh-\no\\) -annu-\np\\) -ṃst-\nq\\) -pt-\nr\\) -ll-\ns\\) -dd-\nt\\) -bbh-\nu\\) -cch-\nv\\) -ṃśch-\nw\\) -īna-\nx\\) - innā-\n\n2\\.\na\\) -t + g-\nb\\) -p + t-\nc\\) -m + a-\nd\\) -p + g-\ne\\) -t + l-\nf\\) -t + h-, -t + dh-\ng\\) -t + m-, - n + m-\n\n3\\.\na\\) -t + l-\nb\\) -t + vowel-/g-/gh-/d-/dh-/b- /bh-/y-/v-/r-/h-\nc\\) -t + zero/k-/kh-/t-/th-/p-/ph- /ṣ-/s- d) -n + zero/vowel-/k-/kh-/g-/gh-/d-/dh-/p-/ph- /b-/bh-/n-/m-/y-/v-/r-/ṣ-/s-/h-\ne\\) -k + vowel-/g- /gh-/j-/jh-/ḍ-/ḍh-/d-/dh-/b-/bh-/y-/v-/r-/l-/h-\nf\\) -k + zero/k-/kh-/c-/ch-/ṭ-/ṭh-/t-/th-/p-/ph-/ś- /ṣ-/s-\ng\\) -p + zero/k-/kh-/c-/ch-/ṭ-/ṭh-/t-/th-/p- /ph-/ś-/ṣ-/s-\nh\\) -n + t-/th-\n\n4\\.\na\\) -p, -b, -m\nb\\) -m, -ṃ\nc\\) -n, -ṃś, -ñ, - ṃṣ, -ṇ, -ṃs, -\n\n\nd\\) -t, -d, -c, -j, -ṭ, -ḍ, -n, -l\ne\\) - ān, -āṃś, -āñ, -āṃṣ, -āṇ, -āṃs, -ā\n\n\nf\\) -an, -ann, -añ, -aṃṣ, -aṇ, -aṃs, -a\n\n\n\n5\\.\n1\\) vṛkṣāt patati/He falls from the tree. (‘flies from the tree’ if a bird is being talked about)\n2\\) vṛkṣāt avapatati/He falls down from the tree (‘flies down from the tree’ if a bird is being talked about)\n3\\) kumāram eva/ the prince (ACCSG) indeed\n4\\) ślokam avagacchāmi/I understand the verse.\n5\\) siṃhāt na vidravati/He does not run away from the lion.\n6\\) gṛhāt hi/from the house indeed\n7\\) narān ca kumārān ca paśyāmi/I see the men and young men/princes.\n8\\) mitram upaveśayati/He makes (his) friend sit down/He causes him to sit down.\n9\\) kṣatriyān jayati/He defeats/conquers the warriors.\n(As always, 3rd Sg can imply ‘he’, ‘she’ or ‘it’.)\n\n6\\. pūrvajanmakṛtaṃ karma taddaivamiti kathyate । tasmātpuruṣakāreṇa yatnaṃ kuryādatandritaḥ ॥\n\nasmiṃstu nirguṇaṃ gotre nāpatyamupajāyate । ākare padmarāgāṇāṃ janma kācamaneḥ kutaḥ ॥\n\nyasmācca yena ca yathā ca yadā ca yacca । yāvacca yatra ca śubhāśubhamātmakarma ॥ tasmācca tena ca tathā ca tadā ca tacca । tāvacca tatra ca vidhātṛvaśādupaiti ॥\n\nkaccijjñātīngurūnvṛddhāndaivatāṃstāpasānapi । caityāṃśca vṛkṣānkalyāṇānbrāhmaṇāṃśca namasyasi ॥ kaccicchokaḥ na manyuḥ vā tvayā protpādyate anagha ।\n\nREADINGS\n\nIntroducing the story of the brahmin and the mongoose\nHe who, not having recognised reality, goes towards the rule of anger (is ruled by anger). He will soon be parted from his friend, like the brahmin from the mongoose.\n\nThe importance of the earth\nIndeed all is born in the earth, all perishes in the earth. The earth is the resting-place for creatures, the earth is indeed (like) a shelter. Of whom the earth is (who has control over the earth), of him the whole world is (he controls the entire world), both standing and moving. Thus (‘there’, ‘in this matter’), very greedy, kings kill each other. \n\nThe fates of warriors\nAnd you should not even mourn them, o ruler, who have been killed in the fight. If the scriptures are right, they have gone (taken) the highest path. Having been killed, he (the warrior) takes (goes to) heaven, and having killed he takes (receives) fame. Both are great for us. There is no fruitlessness in battle.\n", "Catalog/Sanskrit-Study/The Cambridge Introduction to Sanskrit - Answers to Chapter 11 Exercises.md": "---\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 11 Exercises\"\nsubtitle: \"\"\nauthor:\n  - Antonia M. Ruppel\neditor: []\ntranslator: []\nyear:\npublisher: \"\"\nseries: \"\"\nvolume: \"\"\ncontainer: \"\"\nsubject:\n  - Sanskrit-Study\ntype: other\nlanguage:\n  - Sanskrit\n  - English\npages: 1\ntext: searchable\nprint: false\nfiles:\n  - \"[[Chapter_11.pdf]]\"\n  - \"[[CIS - Answers to Chapter 11 Exercises (Ruppel)]]\"\naliases: []\n---\n\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 11 Exercises\n\n```dataviewjs\nawait dv.view(\"Templates/Views/open-pdf\")\n```\n\n**Checked against the file** on 10 November 2026.\n\nAnswer key to the Chapter 11 exercises; belongs with [[The Cambridge Introduction 18 - Chapter 11 Introduction to External Sandhi I Consonant Sandhi|Chapter 11]].\n", "Study/Sanskrit/CIS - Answers to Chapter 12 Exercises (Ruppel).md": "---\ntype: other\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 12 Exercises\"\nauthor:\n  - Antonia M. Ruppel\nwork: \"[[The Cambridge Introduction to Sanskrit - Answers to Chapter 12 Exercises]]\"\nsource_pdf: Library/Sanskrit/Chapter_12.pdf\npage_range: \"1\"\npdf_pages: 1–1\ntext_source: PDF text layer (born-digital), PyMuPDF; Devanagari the text layer garbles rebuilt from the printed transliteration or read from the page image\nconverted: 2026-11-10\n---\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 12 Exercises\n\nAntonia M. Ruppel.\n\nConverted from the PDF on 10 Nov 2026. Each PDF page starts with `*[p. N]*`, the printed page number (or the PDF page where none is printed), ending in the block id `^pgK` for PDF page K. The PDF stays on the computer: open it from [[The Cambridge Introduction to Sanskrit - Answers to Chapter 12 Exercises|the catalog note]].\n\n> [!note] Devanagari\n> The PDF's text layer garbles most of the Devanagari. It is rebuilt here from the printed transliteration (the note on typos was read from the page image and is as printed); check it against the PDF when it matters.\n\n*[p. 1]* ^pg1\n\nCHAPTER 12\n\n1\\.\n1\\) paryanunayāmaḥ –› pari+anu+√nī\n2\\) saṃnibhṛtaḥ –› sam+ni+√bhṛ\n3\\) apātiṣṭhāvaḥ –› apa+ā+√sthā\n4\\) pratyupadravasi –› prati+upa+√dru\n5\\) samutkṣipataḥ –› sam+ud+√kṣip\n6\\) apātiṣṭhāva –› apa+ā+√sthā or apa+ā+√sthā\n7\\) āgacchat –› ā+√gam\n8\\) vyapāgacchāma –› vi+apa+√gam\n9\\) abhyavanayet –› abhi+ava+√nī\n10\\) anūttiṣṭhati –› anu+ud+√sthā\n11\\) prodgacchanti –› pra+ud+√gam\n12\\) anvāgacchat –› anu+ā+√gam\n13\\) anvāgacchati –› anu+ā+√gam\n14\\) anvagacchat –› anu+√gam\n15\\) pratyānayati –› prati+ā+√nī\n\n2\\.\n1\\) patati –› apatat ‘he fell; he flew’\n2\\) pūjayāvaḥ –› apūjayāva ‘we both honoured’\n3\\) gacchanti –› agacchan ‘they went’\n4\\) saṃyajathaḥ –› samayajatam ‘you both worshipped together’\n5\\) āgacchan –› āgacchanti ‘they come’\n6\\) utpatatha –› udapatata ‘you flew out’\n7\\) aviśāma –› viśāmaḥ ‘we enter’\n8\\) upaviśāmaḥ –› upāviśāma ‘we sat down’\n9\\) parigacchati –› paryagacchat ‘he went around’\n10\\) rohāmaḥ –› arohāma ‘we ascended’\n11\\) prāviśatām –› praviśataḥ ‘they both enter’\n12\\) anvadravaḥ –› anudravasi ‘you run towards’\n13\\) āgacchasi –› āgacchaḥ ‘you came’\n14\\) jayathaḥ –› ajayatam ‘you both won’\n15\\) vasasi –› avasaḥ ‘you lived’\n16\\) abhyabhavaḥ –› abhibhavasi ‘you overpower’\n\n3\\.\n1\\) tarāmaḥ –› tarema ‘we should cross’\n2\\) vadasi –› vadeḥ ‘you should speak’\n3\\) harathaḥ –› haretam ‘you both should take’\n4\\) viśanti –› viśeyuḥ ‘they should enter’\n5\\) tyajema –› tyajāmaḥ ‘we leave behind’\n6\\) vigacchasi –› vigaccheḥ ‘you should go away’\n7\\) praviśataḥ –› praviśetām ‘they both should enter’\n8\\) dahāmi –› daheyam ‘I should burn’\n9\\) pateyam –› patāmi ‘I fall’\n10\\) muñcāvaḥ –› muñceva ‘we both should release’\n11\\) bhavati –› bhavet ‘he should be’\n12\\) avataranti –› avatareyuḥ ‘they should ascend’\n13\\) āgaccheyuḥ –› āgacchanti ‘they come’\n\n4\\.\na\\) abharat\nb\\) anayat\nc\\) atiṣṭhat\nd\\) arohat\ne\\) avātarat\nf\\) abhyadravat\ng\\) abhyabhavat\nh\\) upāviśat, asīdat\ni\\) avadat\nj\\) udatiṣṭhat\nk\\) ayajat\nl\\) agacchat\nm\\) adahat\n\n5\\.\na\\) jīvema\nb\\) paśyema\nc\\) tarema\nd\\) prasīdema or tuṣyema\ne\\) rohema\nf\\) vardhema\ng\\) muñcema\nh\\) snihyema\ni\\) icchema\nj\\) śocema\nk\\) uttiṣṭhema\nl\\) darśayema\n\n6\\.\n1\\) naraḥ · purāt pratyāgatya bālāyai vṛkṣam adarśayat.\nHaving come back from the city, the man showed the tree to the girl.\n2\\) devānām prabhām paśyeḥ · iti naraḥ · mitram avadat.\n‘You ought to see the splendour of the gods’, the man said to his friend.\n3\\) ugram kṣatriyam dṛṣṭvā naraḥ · mitram api kṣatriyam apaśyaḥ · iti · apṛcchat.\nHaving seen the horrible warrior, the man asked his friend: ‘Did you see the warrior?’\n4\\) devān yajñaiḥ · toṣayema · iti śūraḥ · avadat.\n‘We should please the gods with sacrifices’, the hero said.\n5\\) yuddhe yathā nagarāṇi naṣṭāni (typo: not naṣṭhāni) tathā janāḥ · naṣṭāḥ (typo: not naṣṭhāḥ).\nJust as the cities were destroyed in battle, so were the people/so did the people perish. (Note typos: नष्तानि, नष्टाः:, not नष्ठानि, नष्ठाः:.)\n6\\) ugraḥ · nṛpaḥ · janebhyaḥ · dānāni · āptum aicchat.\nThe terrible king wanted to get gifts from [his] people.\n7\\) padmam darśayeḥ · iti bālau kanyām avadatām.\n‘You should show [us] the lotus’, the two boys said to the girl.\n8\\) bhadre kāle punar samāgacchema · iti · uktvā kumāraḥ kṣaṇād apāgacchat.\nHaving said ‘At the right time, we should come together/meet again’, the young man left immediately.\n9\\) kṣatriyasya vacanāni śrutvā narāḥ · atra niṣadya cintāḥ · ca vismareḥ · iti · avadan.\nHaving heard the words of the warrior, the men said: ‘You should/Please sit down here and forget your worries.’ (lit: ‘having sat down, you should). Note Errata: the ca from this sentence should be omitted.\n10\\) yathā janāḥ · kṣetre sthitasya vṛkṣasya phalaiḥ tuṣyanti tathā · aśvāḥ.\nJust as the people rejoice about the fruit of the tree that is standing in the field, so do the horses.\n\nREADINGS\n\nSome things are worth great sacrifice\nOne should abandon a single person for the sake of a family, a family for the sake of a village, a village for the sake of a nation, and the earth for one’s own soul.\n\nSītā vividly describes her loyalty to her husband\nEven if the sky and (together with) the stars fell, even if the earth became fragmented/broke up, even if the fires went towards coldness/cooled down, I would not leave Rāma.\n\nThe power of emotion over reason\nJust as the fire is covered by smoke, (just as) a mirror (is covered) by dust, just as the embryo is covered by a womb, so is the mind covered by passion.\n", "Catalog/Sanskrit-Study/The Cambridge Introduction to Sanskrit - Answers to Chapter 12 Exercises.md": "---\ntitle: \"The Cambridge Introduction to Sanskrit: Answers to Chapter 12 Exercises\"\nsubtitle: \"\"\nauthor:\n  - Antonia M. Ruppel\neditor: []\ntranslator: []\nyear:\npublisher: \"\"\nseries: \"\"\nvolume: \"\"\ncontainer: \"\"\nsubject:\n  - Sanskrit-Study\ntype: other\nlanguage:\n  - Sanskrit\n  - English\npages: 1\ntext: searchable\nprint: false\nfiles:\n  - \"[[Chapter_12.pdf]]\"\n  - \"[[CIS - Answers to Chapter 12 Exercises (Ruppel)]]\"\naliases: []\n---\n\n# The Cambridge Introduction to Sanskrit: Answers to Chapter 12 Exercises\n\n```dataviewjs\nawait dv.view(\"Templates/Views/open-pdf\")\n```\n\n**Checked against the file** on 10 November 2026.\n\nAnswer key to the Chapter 12 exercises; belongs with [[The Cambridge Introduction 19 - Chapter 12 Imperfect Indicative and Present Potential|Chapter 12]].\n"};
  const base = ad.getBasePath(), DL = 'C:\\Users\\welln\\OneDrive\\Documents\\Downloads\\Add to Obsidian\\';
  const unresBefore = Object.values(app.metadataCache.unresolvedLinks).reduce((a, m) => a + Object.keys(m).length, 0);
  for (let n = 4; n <= 12; n++) {
    const src = DL + 'Chapter_' + n + '.pdf', dst = 'Library/Sanskrit/Chapter_' + n + '.pdf';
    if (!fs.existsSync(src)) { E('no source ' + src); continue; }
    if (await ad.exists(dst)) { E('exists ' + dst); continue; }
    L('copy ' + src + ' (' + fs.statSync(src).size + ' bytes) -> ' + dst);
    if (!DRY) { fs.copyFileSync(src, path.join(base, dst)); await ad.reconcileFile?.(dst, dst); }
  }
  for (const [p, t] of Object.entries(B)) {
    if (await ad.exists(p)) { E('exists ' + p); continue; }
    L('create ' + p + ' (' + t.length + ' chars)');
    if (!DRY) await app.vault.create(p, t);
  }
  if (!DRY) {
    await new Promise(r => setTimeout(r, 4000));
    D.unresBefore = unresBefore; D.unresAfter = Object.values(app.metadataCache.unresolvedLinks).reduce((a, m) => a + Object.keys(m).length, 0);
    D.newUnresolved = [];
    for (const p of Object.keys(B)) { const u = app.metadataCache.unresolvedLinks[p] || {}; for (const k of Object.keys(u)) D.newUnresolved.push(p + ' -> ' + k); }
    D.pdfs = [];
    for (let n = 4; n <= 12; n++) { const f = app.vault.getAbstractFileByPath('Library/Sanskrit/Chapter_' + n + '.pdf'); D.pdfs.push(f ? f.stat.size : null); }
  }
  await ad.write('.work/out/' + JOB + '.detail.json', JSON.stringify(D, null, 1));
  return `${JOB}${DRY ? ' DRY' : ''}: ${D.log.length} steps, ${D.errors.length} errors${D.errors.length ? ': ' + D.errors.slice(0, 3).join(' | ').slice(0, 300) : ''}${DRY ? '' : '; unresolved ' + D.unresBefore + ' -> ' + D.unresAfter + '; new-note unresolved ' + D.newUnresolved.length}`;
})()
